insert into public.data_sources values ('SAMPLE_FOODS_V1','NourishCart illustrative food values','NourishCart team (sample data)','1.0.0',null,'Internal sample data; no external dataset copied','Sample values – not for dietary prescription','not_required',true,'Rounded, approximate per-100 g values entered by the team for UI and engine testing. Some values are deliberately left unknown. Not verified against IFCT 2017 or INDB, and must be replaced by a licensed dataset before public advice.');
